BEGIN;
CREATE TABLE governance_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_code text NOT NULL,title text NOT NULL,document_class text NOT NULL,owner_role text NOT NULL,approval_authority text NOT NULL,status text NOT NULL CHECK(status IN ('draft','consultation','legal_review','approval_pending','approved','superseded','retired','blocked')),version text NOT NULL,effective_at timestamptz,review_due_at timestamptz,content_hash text NOT NULL,storage_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,document_code,version));
CREATE TABLE governance_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_id uuid NOT NULL REFERENCES governance_documents(id),approval_type text NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id),decision text NOT NULL CHECK(decision IN ('approved','rejected','returned','recused')),decision_at timestamptz NOT NULL DEFAULT now(),comment text,evidence_hash text,UNIQUE(document_id,approval_type,actor_user_id));
CREATE TABLE board_meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),meeting_code text NOT NULL,meeting_at timestamptz NOT NULL,meeting_type text NOT NULL,quorum_met boolean NOT NULL DEFAULT false,agenda_storage_key text,minutes_storage_key text,minutes_status text NOT NULL DEFAULT 'draft',approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,meeting_code));
CREATE TABLE board_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),meeting_id uuid NOT NULL REFERENCES board_meetings(id),action_code text NOT NULL,title text NOT NULL,motion text NOT NULL,vote_for integer NOT NULL DEFAULT 0,vote_against integer NOT NULL DEFAULT 0,vote_abstain integer NOT NULL DEFAULT 0,recusals jsonb NOT NULL DEFAULT '[]',status text NOT NULL CHECK(status IN ('proposed','adopted','rejected','tabled','rescinded')),effective_at timestamptz,UNIQUE(meeting_id,action_code));
CREATE TABLE policy_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_id uuid NOT NULL REFERENCES governance_documents(id),requestor_user_id uuid NOT NULL REFERENCES users(id),scope text NOT NULL,reason text NOT NULL,compensating_controls jsonb NOT NULL DEFAULT '[]',status text NOT NULL CHECK(status IN ('pending','approved','rejected','expired','revoked')),approved_by uuid REFERENCES users(id),approved_at timestamptz,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'approved' OR (approved_by IS NOT NULL AND expires_at IS NOT NULL)));
CREATE TABLE institutional_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),cycle text NOT NULL,unit text NOT NULL,outcome_code text NOT NULL,measure text NOT NULL,benchmark text NOT NULL,result jsonb,analysis text,improvement_action text,action_owner uuid REFERENCES users(id),due_at timestamptz,reassessment_at timestamptz,status text NOT NULL DEFAULT 'planned',evidence_storage_key text,UNIQUE(tenant_id,cycle,unit,outcome_code,measure));
CREATE INDEX governance_review_due ON governance_documents(tenant_id,status,review_due_at);CREATE INDEX policy_exception_expiry ON policy_exceptions(tenant_id,status,expires_at);CREATE INDEX institutional_assessment_cycle ON institutional_assessments(tenant_id,cycle,status);
ALTER TABLE governance_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE governance_approvals ENABLE ROW LEVEL SECURITY;ALTER TABLE board_meetings ENABLE ROW LEVEL SECURITY;ALTER TABLE board_actions ENABLE ROW LEVEL SECURITY;ALTER TABLE policy_exceptions ENABLE ROW LEVEL SECURITY;ALTER TABLE institutional_assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY governance_documents_tenant ON governance_documents USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY governance_approvals_tenant ON governance_approvals USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY board_meetings_tenant ON board_meetings USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY board_actions_tenant ON board_actions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY policy_exceptions_tenant ON policy_exceptions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY institutional_assessments_tenant ON institutional_assessments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
